/**
 * MIRA — OpenAI Token Usage Extractor v1.0
 * Source: n8n Execution API (includeData=true)
 * Reads actual usage, not estimates.
 */

const execution = $input.first().json;
const runData = execution.data?.resultData?.runData ?? {};

const models = [];
const records = [];

const num = value => {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? n : null;
};

for (const [nodeName, runs] of Object.entries(runData)) {
  for (const [runIndex, run] of (runs ?? []).entries()) {
    const aiItems = run.data?.ai_languageModel ?? [];

    for (const group of aiItems) {
      for (const item of (Array.isArray(group) ? group : [])) {
        const json = item?.json ?? {};
        const usage = json.tokenUsage ?? {};

        const input = num(
          usage.promptTokens ?? usage.input_tokens
        );

        const output = num(
          usage.completionTokens ?? usage.output_tokens
        );

        if (input !== null && output !== null) {
          records.push({
            node: nodeName,
            run_index: runIndex,
            input_tokens: input,
            output_tokens: output,
            total_tokens: num(usage.totalTokens) ?? input + output,
            model: json.response?.generations?.[0]?.[0]
              ?.generationInfo?.model_name ?? null
          });
        }
      }
    }

    // Fallback: tracing metadata, only if no AI item
    // usage was captured for this node execution.
    if (!records.some(
      r => r.node === nodeName && r.run_index === runIndex
    )) {
      const usage =
        run.metadata?.tracing?.gen_ai?.usage ?? {};

      const input = num(usage.input_tokens);
      const output = num(usage.output_tokens);

      if (input !== null && output !== null) {
        records.push({
          node: nodeName,
          run_index: runIndex,
          input_tokens: input,
          output_tokens: output,
          total_tokens: input + output,
          model: null
        });
      }
    }
  }
}

const totals = records.reduce((acc, r) => {
  acc.input_tokens += r.input_tokens;
  acc.output_tokens += r.output_tokens;
  acc.total_tokens += r.total_tokens;
  return acc;
}, {
  input_tokens: 0,
  output_tokens: 0,
  total_tokens: 0
});

return [{
  json: {
    execution_id: execution.id ?? null,
    workflow_id: execution.workflowId ?? null,
    usage_found: records.length > 0,
    model_call_count: records.length,
    generation_input_tokens:
      records.length ? totals.input_tokens : null,
    generation_output_tokens:
      records.length ? totals.output_tokens : null,
    generation_total_tokens:
      records.length ? totals.total_tokens : null,
    model_usage_records: records
  }
}];

const usage = $input.first().json;

const execution = $('Fetch Execution Details').first().json;
const runData =
  execution.data?.resultData?.runData ?? {};

const candidates = [];

for (const runs of Object.values(runData)) {
  for (const run of runs ?? []) {
    for (const group of run.data?.main ?? []) {
      for (const item of group ?? []) {
        const j = item?.json ?? {};

        if (j.trace_id) candidates.push(j.trace_id);
        if (j.root_trace_id) candidates.push(j.root_trace_id);
      }
    }
  }
}

const traceId = candidates.find(
  x => /^[0-9a-f]{32}$/i.test(String(x))
) ?? null;

return [{
  json: {
    ...usage,
    trace_id: traceId,
    ready_for_langfuse:
      usage.usage_found === true &&
      traceId !== null
  }
}];

/**
 * MIRA — Build Token OTEL Payload v1.0
 * One generation observation per model usage record.
 *
 * Run Once for All Items.
 */

const x = $input.first().json;

if (!x.ready_for_langfuse) {
  throw new Error('Missing usage or Langfuse trace ID');
}

const execution = $('Fetch Execution Details').first().json;
const runData = execution.data?.resultData?.runData ?? {};

const validId = s => /^[0-9a-f]{16}$/i.test(String(s ?? ''));

let parentSpanId = null;

// Prefer the agent span returned by the completed workflow.
for (const runs of Object.values(runData)) {
  for (const run of runs ?? []) {
    for (const group of run.data?.main ?? []) {
      for (const item of group ?? []) {
        const j = item?.json ?? {};
        if (
          j.trace_id === x.trace_id &&
          validId(j.span_id)
        ) {
          parentSpanId = j.span_id;
        }
      }
    }
  }
}

if (!parentSpanId) {
  throw new Error(
    'Cannot identify agent parent span; verify Return Agent Result'
  );
}

// Deterministic span IDs prevent duplicate observations
// when the same execution is reprocessed.
function spanIdFor(executionId, node, index) {
  const input = `${executionId}:${node}:${index}`;
  let a = 2166136261;
  let b = 2246822519;

  for (let i = 0; i < input.length; i++) {
    const c = input.charCodeAt(i);
    a = Math.imul(a ^ c, 16777619) >>> 0;
    b = Math.imul(b ^ c, 3266489917) >>> 0;
  }

  const id =
    a.toString(16).padStart(8, '0') +
    b.toString(16).padStart(8, '0');

  return id === '0000000000000000'
    ? '0000000000000001'
    : id;
}

const timestamp = t =>
  String(BigInt(Math.round(t)) * 1000000n);

const startMs = Date.parse(
  execution.startedAt ?? execution.createdAt ?? ''
);

const endMs = Date.parse(
  execution.stoppedAt ?? execution.finishedAt ?? ''
);

if (!Number.isFinite(startMs) || !Number.isFinite(endMs)) {
  throw new Error('Execution timestamps unavailable');
}

const attr = (key, value) => ({
  key,
  value: typeof value === 'number'
    ? { intValue: String(value) }
    : { stringValue: String(value) }
});

const spans = x.model_usage_records.map((r, index) => ({
  traceId: x.trace_id,
  spanId: spanIdFor(x.execution_id, r.node, r.run_index ?? index),
  parentSpanId,
  name: `MIRA Model Usage — ${r.node}`,
  kind: 3,
  startTimeUnixNano: timestamp(startMs),
  endTimeUnixNano: timestamp(endMs),
  attributes: [
    attr('langfuse.observation.type', 'generation'),
    attr('gen_ai.provider.name', 'openai'),
    attr('gen_ai.operation.name', 'chat'),
    attr('gen_ai.request.model', r.model || 'unknown'),
    attr('gen_ai.usage.input_tokens', r.input_tokens),
    attr('gen_ai.usage.output_tokens', r.output_tokens),
    attr('langfuse.observation.metadata.n8n_execution_id', x.execution_id),
    attr('langfuse.observation.metadata.usage_source', 'n8n_execution_api')
  ]
}));

return [{
  json: {
    execution_id: x.execution_id,
    trace_id: x.trace_id,
    parent_span_id: parentSpanId,
    generation_count: spans.length,
    otel_payload: {
      resourceSpans: [{
        resource: {
          attributes: [
            attr('service.name', 'MIRA-TokenCollector')
          ]
        },
        scopeSpans: [{
          scope: { name: 'mira-token-collector' },
          spans
        }]
      }]
    }
  }
}];
